package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.Set;
import net.officefloor.hq.app.role.RoleRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The records that only report figures: they never carry the steward a delegate acts for. */
    private static final Set<String> FIGURES = Set.of("ROLLUP", "TOTALS", "ALERT");

    private final Path file;

    private final ObjectProvider<RoleRepository> roles;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<RoleRepository> roles) {
        this.file = Path.of(path);
        this.roles = roles;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A record of a change made by a user
     *  name while the sheet's today is inside a delegation of the steward role to it ends with for=&lt;the steward
     *  who delegated&gt;. */
    public void record(String entry) {
        write(entry + forDelegator(entry));
    }

    /** " for=&lt;steward&gt;" when the record's by= acts for a steward on its sheet= today, else "". */
    private String forDelegator(String entry) {
        int space = entry.indexOf(' ');
        if (space < 0 || FIGURES.contains(entry.substring(0, space))) {
            return "";
        }
        String sheet = field(entry, "sheet");
        String by = field(entry, "by");
        if (sheet == null || by == null || by.isEmpty()) {
            return "";
        }
        String delegator = roles.getObject().delegatorOf(sheet, by);
        return delegator == null ? "" : " for=" + delegator;
    }

        }
        return new ClaimInput(value, parsed, note, corrects.isEmpty() ? null : corrects,
                ref.isEmpty() ? null : ref, Tags.normalise(tagsField));
    }

    /** The claim the input makes for the person, not yet saved; refused as BuildClaim refuses it. Its due-by is the
     *  terms-th business day after its date, skipping weekends and the sheet's holidays now on its list. */
    public static Claim make(ClaimInput input, Sheet sheet, Person person, ClaimRepository repository,
            PeriodRepository periods, PersonGradeRepository grades, HolidayRepository holidays) throws InvalidClaimException {
        LocalDate date = input.date() != null ? input.date() : sheet.entryDateInForce();
        int terms = sheet.termsFor(person.getTerms(), grades.gradesOf(person).on(date), date);
        LocalDate dueBy = holidays.dueBy(sheet.getId(), date, terms);
        if (periods.isClosedOn(sheet.getId(), dueBy)) {
            throw new InvalidClaimException("No claim can be added in a closed period.");
        }
        if (person.retiredOn(date)) {
            throw new InvalidClaimException("No claim can be dated after the person's retirement date.");
        }
        LocalDate correctsDate = repository.checkCorrects(sheet.getId(), person.getId(), input.corrects());
        repository.checkRef(sheet.getId(), null, input.ref());
        Claim claim = new Claim(sheet.getId(), person.getId(), input.amount(), date, input.note(), input.corrects());
        claim.setCorrectsDate(correctsDate);
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setLateEntry(periods.isSoftClosedOn(sheet.getId(), dueBy));
        claim.fixDue(date, terms, holidays.datesOf(sheet.getId()));
        return claim;
    }

    /** Records the claim's adding (its ref, then its tags, at the end, when it has them), and after it, when it is a late entry, its LATE_ENTRY. */
    public static void auditAdded(Claim claim, String personName, String by, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_ADDED", claim, personName, by)
                + (claim.getRef() == null ? "" : " ref=" + claim.getRef())
                + (claim.getTags() == null ? "" : " tags=" + claim.getTags()));
        if (claim.isLateEntry()) {
            audit.record(ClaimAudit.line("LATE_ENTRY", claim, personName, by));
        }
    }

    /** Writes the claim's status log entry as LogClaimStatus does, made by the given user. */
    public static void log(Claim claim, Sheet sheet, ClaimLogRepository log, PersonRepository people,
            RateRepository rates, PersonGradeRepository grades, String by) {
        BigDecimal due = people.findById(claim.getPersonId())
                .map(p -> new ClaimFigures(rates.findInChain(claim.getSheetId()),
                        grades.gradesOf(p), sheet).due(claim))
                .orElse(null);
        log.saveAndFlush(new ClaimLog(claim, by, sheet.getToday(), due));
    }
}
package net.officefloor.hq.app.claim;

/** A claim's audit line: the event, sheet, user, person, amount as the screen shows it, date, and the claim's
 * number when it has one. */
public final class ClaimAudit {

    private ClaimAudit() {
    }

    public static String line(String event, Claim claim, String person, String user) {
        return line(event, claim, person, user, claim.getNumber());
    }

    static String line(String event, Claim claim, String person, String user, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person
                + " amount=" + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}

